def run_sync(fetch, max_items, on_item=None):
    items = []
    attempts = 0
    while len(items) < max_items:
        attempts += 1
        try:
            batch = fetch(len(items))
        except IOError:
            continue
        if on_item:
            on_item(batch)
        items.extend(batch)
    return items[: max_items - 1]
EOF

